steps.raw:
SELECT PetType, AVG(pet_age) AS avg_age, MAX(pet_age) AS max_age
FROM Pets
GROUP BY PetType;

SELECT v.vote_id, a.area_code
FROM VOTES v
JOIN AREA_CODE_STATE a ON v.state = a.state;

SELECT d.age, AVG(CAST(d.age AS REAL)) OVER () AS average_age
FROM Dogs d
WHERE d.dog_id IN (SELECT DISTINCT dog_id FROM Treatments);

SELECT t.treatment_type_code, SUM(t.cost_of_treatment) AS total_cost
FROM Treatments t
GROUP BY t.treatment_type_code;

SELECT t.date_of_treatment, p.first_name, p.last_name
FROM Treatments t
JOIN Professionals p ON t.professional_id = p.professional_id;

SELECT t.cost_of_treatment, tt.treatment_type_description
FROM Treatments t
JOIN Treatment_Types tt ON t.treatment_type_code = tt.treatment_type_code;

SELECT d.dog_id, d.date_arrived, d.date_departed
FROM Dogs d
WHERE d.dog_id IN (SELECT DISTINCT dog_id FROM Treatments);

SELECT b.breed_name, s.size_description
FROM Breeds b
CROSS JOIN Sizes s;

SELECT p.first_name, p.last_name, t.treatment_type_code
FROM Professionals p
JOIN Treatments t ON p.professional_id = t.professional_id;
